#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ld8(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void st8(float *p, v8 v) { memcpy(p, &v, sizeof v); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int acc, int mr, int nr)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};
    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }
    if (mr == MR && nr == NR) {
        float *r;
        if (acc) {
            r = c + 0 * ldc; st8(r, ld8(r) + c00); st8(r + 8, ld8(r + 8) + c01);
            r = c + 1 * ldc; st8(r, ld8(r) + c10); st8(r + 8, ld8(r + 8) + c11);
            r = c + 2 * ldc; st8(r, ld8(r) + c20); st8(r + 8, ld8(r + 8) + c21);
            r = c + 3 * ldc; st8(r, ld8(r) + c30); st8(r + 8, ld8(r + 8) + c31);
            r = c + 4 * ldc; st8(r, ld8(r) + c40); st8(r + 8, ld8(r + 8) + c41);
            r = c + 5 * ldc; st8(r, ld8(r) + c50); st8(r + 8, ld8(r + 8) + c51);
        } else {
            r = c + 0 * ldc; st8(r, c00); st8(r + 8, c01);
            r = c + 1 * ldc; st8(r, c10); st8(r + 8, c11);
            r = c + 2 * ldc; st8(r, c20); st8(r + 8, c21);
            r = c + 3 * ldc; st8(r, c30); st8(r + 8, c31);
            r = c + 4 * ldc; st8(r, c40); st8(r + 8, c41);
            r = c + 5 * ldc; st8(r, c50); st8(r + 8, c51);
        }
    } else {
        float t[MR * NR];
        st8(t + 0 * NR, c00); st8(t + 0 * NR + 8, c01);
        st8(t + 1 * NR, c10); st8(t + 1 * NR + 8, c11);
        st8(t + 2 * NR, c20); st8(t + 2 * NR + 8, c21);
        st8(t + 3 * NR, c30); st8(t + 3 * NR + 8, c31);
        st8(t + 4 * NR, c40); st8(t + 4 * NR + 8, c41);
        st8(t + 5 * NR, c50); st8(t + 5 * NR + 8, c51);
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (acc) c[i * ldc + j] += t[i * NR + j];
                else     c[i * ldc + j]  = t[i * NR + j];
            }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npan = (n + NR - 1) / NR;
    float *Bp = aligned_alloc(64, (size_t)npan * NR * KC * sizeof(float) + 64);

    #pragma omp parallel
    {
        float *Ap = aligned_alloc(64, (size_t)(MC + MR) * KC * sizeof(float));
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc > 0;

            #pragma omp for schedule(static)
            for (int p = 0; p < npan; p++) {
                int j0 = p * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p * NR * kc;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(pc + k) * n + j0;
                    float *d = dst + k * NR;
                    if (nr == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }

            #pragma omp for schedule(dynamic, 1)
            for (int ic = 0; ic < n; ic += MC) {
                int mc = n - ic < MC ? n - ic : MC;
                int mpan = (mc + MR - 1) / MR;
                for (int q = 0; q < mpan; q++) {
                    int i0 = q * MR;
                    int mr = mc - i0 < MR ? mc - i0 : MR;
                    float *d = Ap + (size_t)q * MR * kc;
                    const float *src = A + (size_t)(ic + i0) * n + pc;
                    for (int k = 0; k < kc; k++) {
                        int i = 0;
                        for (; i < mr; i++) d[k * MR + i] = src[(size_t)i * n + k];
                        for (; i < MR; i++) d[k * MR + i] = 0.0f;
                    }
                }
                for (int p = 0; p < npan; p++) {
                    int j0 = p * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    const float *bp = Bp + (size_t)p * NR * kc;
                    for (int q = 0; q < mpan; q++) {
                        int i0 = q * MR;
                        int mr = mc - i0 < MR ? mc - i0 : MR;
                        kernel(kc, Ap + (size_t)q * MR * kc, bp,
                               C + (size_t)(ic + i0) * n + j0, n, acc, mr, nr);
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
